import type {
  BudgetEstimate,
  DayPlan,
  DifficultyLevel,
  PlanRequest,
  PlanResponse,
} from "@/types/plan";

const DISCLAIMER =
  "DEMO CONTENT: this itinerary, packing list, and budget are sample data " +
  "for UI development. They are not generated by a real trip-planning model.";

function enumerateDates(startDate: string, endDate: string): string[] {
  const start = new Date(startDate);
  const end = new Date(endDate);
  const dates: string[] = [];

  for (
    let current = new Date(start);
    current <= end;
    current.setDate(current.getDate() + 1)
  ) {
    dates.push(current.toISOString().slice(0, 10));
  }

  return dates.length > 0 ? dates : [startDate];
}

function inferDifficulty(constraints: string | undefined): DifficultyLevel {
  const text = (constraints ?? "").toLowerCase();
  if (text.includes("beginner") || text.includes("knee") || text.includes("injury")) {
    return "easy";
  }
  if (text.includes("advanced") || text.includes("experienced")) {
    return "challenging";
  }
  return "moderate";
}

function inferBudgetTotal(constraints: string | undefined): number {
  const match = (constraints ?? "").match(/(\d{3,6})/);
  if (match) {
    return Number(match[1]);
  }
  return 5000;
}

export function generateMockPlanResponse(request: PlanRequest): PlanResponse {
  const difficulty = inferDifficulty(request.constraints);
  const budgetTotal = inferBudgetTotal(request.constraints);
  const dates = enumerateDates(request.startDate, request.endDate);

  const itinerary: DayPlan[] = dates.map((date, index) => ({
    date,
    dayLabel: `Day ${index + 1}`,
    summary:
      index === 0
        ? `Arrival and gentle acclimatization walk around ${request.place}.`
        : `Guided outdoor exploration near ${request.place}, paced for a ${difficulty} difficulty level.`,
    activities: [
      {
        name: index === 0 ? "Orientation walk" : "Scenic viewpoint trail",
        durationMinutes: difficulty === "easy" ? 60 : difficulty === "moderate" ? 120 : 180,
        difficulty,
        notes:
          difficulty === "easy"
            ? "Flat terrain, frequent rest stops, low knee strain."
            : "Moderate elevation gain, bring trekking poles.",
      },
      {
        name: "Local viewpoint and tea break",
        durationMinutes: 45,
        difficulty: "easy",
        notes: "Low-exertion stop to hydrate and rest.",
      },
    ],
  }));

  const packingChecklist = [
    "Weatherproof jacket",
    "Sturdy walking shoes with ankle support",
    difficulty === "easy" ? "Knee support brace" : "Trekking poles",
    "Reusable water bottle",
    "First-aid kit",
    "Power bank",
    "Local SIM card and downloaded offline maps",
  ];

  const safetyNotes = [
    "Check local landslide and weather advisories before departure (see risk assessment).",
    "Inform a contact of your daily route and expected return time.",
    "Avoid trails during or immediately after heavy rainfall.",
    request.riskVerdict === "WAIT"
      ? "Risk verdict was WAIT for these dates, so consider rescheduling outdoor activities."
      : "Carry a basic first-aid kit and know the nearest medical facility location.",
  ];

  const budgetEstimate: BudgetEstimate = {
    currency: "INR",
    total: budgetTotal,
    breakdown: {
      stay: Math.round(budgetTotal * 0.4),
      food: Math.round(budgetTotal * 0.25),
      localTransport: Math.round(budgetTotal * 0.2),
      misc: Math.round(budgetTotal * 0.15),
    },
  };

  return {
    destination: request.place,
    startDate: request.startDate,
    endDate: request.endDate,
    itinerary,
    packingChecklist,
    safetyNotes,
    budgetEstimate,
    isMockData: true,
    disclaimer: DISCLAIMER,
  };
}
